import{_ as a,o as i,c as r,a2 as n}from"./chunks/framework.CgxQ0r6v.js";const g=JSON.parse('{"title":"Planificación Académica: Redes (Trimestre 2)","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Redes/Planificacion_Trimestre_II-V.md","filePath":"materias/Redes/Planificacion_Trimestre_II-V.md"}'),s={name:"materias/Redes/Planificacion_Trimestre_II-V.md"};function t(o,e,d,l,c,u){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="planificacion-academica-redes-trimestre-2" tabindex="-1">Planificación Académica: Redes (Trimestre 2) <a class="header-anchor" href="#planificacion-academica-redes-trimestre-2" aria-label="Permalink to &quot;Planificación Académica: Redes (Trimestre 2)&quot;">​</a></h1><p>Este trimestre cubre la segunda mitad del contenido programático (Unidades 7 a la 12). Aquí los alumnos pasan de la teoría física a la <strong>configuración lógica, administración y seguridad</strong> de las redes.</p><hr><h2 id="📅-trimestre-2-administracion-enrutamiento-y-seguridad-unidades-7-a-12" tabindex="-1">📅 Trimestre 2: Administración, Enrutamiento y Seguridad (Unidades 7 a 12) <a class="header-anchor" href="#📅-trimestre-2-administracion-enrutamiento-y-seguridad-unidades-7-a-12" aria-label="Permalink to &quot;📅 Trimestre 2: Administración, Enrutamiento y Seguridad (Unidades 7 a 12)&quot;">​</a></h2><p><strong>Periodo:</strong> 04/05/2026 al 17/07/2026</p><h3 id="📝-evaluacion-1-planeacion-y-estandares-de-red-unidades-7-y-12" tabindex="-1">📝 Evaluación 1: Planeación y Estándares de Red (Unidades 7 y 12) <a class="header-anchor" href="#📝-evaluacion-1-planeacion-y-estandares-de-red-unidades-7-y-12" aria-label="Permalink to &quot;📝 Evaluación 1: Planeación y Estándares de Red (Unidades 7 y 12)&quot;">​</a></h3><p><strong>Objetivo:</strong> Diseñar redes locales aplicando los estándares de la industria.</p><ul><li><strong>Planeación LAN:</strong> Diseño e instalación de la infraestructura de red.</li><li><strong>Estándares IEEE:</strong> Clasificación y aplicación práctica.</li><li><strong>Ethernet y Wi-Fi:</strong> Estándares 802.3 (Cableado) y 802.11 (Inalámbrico).</li><li><strong>Actividad:</strong> <strong>Proyecto de Diseño de Red / Laboratorio.</strong> (25%)</li></ul><h3 id="📝-evaluacion-2-direccionamiento-enrutamiento-y-subredes-unidades-10-y-11" tabindex="-1">📝 Evaluación 2: Direccionamiento, Enrutamiento y Subredes (Unidades 10 y 11) <a class="header-anchor" href="#📝-evaluacion-2-direccionamiento-enrutamiento-y-subredes-unidades-10-y-11" aria-label="Permalink to &quot;📝 Evaluación 2: Direccionamiento, Enrutamiento y Subredes (Unidades 10 y 11)&quot;">​</a></h3><p><strong>Objetivo:</strong> Dominar el esquema lógico de direcciones y la segmentación de redes.</p><ul><li><strong>Enrutamiento:</strong> Protocolos enrutados vs de enrutamiento. Topologías lógicas.</li><li><strong>Subredes (Subnetting):</strong> Cálculos de segmentación y razones para implementarlas.</li><li><strong>Protocolo IP:</strong> IPv4 (Generalidades, clases, ejercicios) e IPv6.</li><li><strong>Actividad:</strong> <strong>Examen Práctico / Ejercicios de Subnetting.</strong> (25%)</li></ul><h3 id="📝-evaluacion-3-administracion-y-servicios-de-red-unidad-8" tabindex="-1">📝 Evaluación 3: Administración y Servicios de Red (Unidad 8) <a class="header-anchor" href="#📝-evaluacion-3-administracion-y-servicios-de-red-unidad-8" aria-label="Permalink to &quot;📝 Evaluación 3: Administración y Servicios de Red (Unidad 8)&quot;">​</a></h3><p><strong>Objetivo:</strong> Configurar y administrar servicios vitales en un entorno de red (Sistemas Linux/Windows).</p><ul><li><strong>Configuración Base:</strong> TCP/IP, Tarjeta de red y demonios de red (inetd/xinetd).</li><li><strong>Servicios de Transferencia:</strong> FTP, SFTP, SCP. Acceso remoto con SSH/Telnet.</li><li><strong>Servicios de Resolución y Web:</strong> DNS, HTTP (Apache), NFS/Samba.</li><li><strong>Actividad:</strong> <strong>Laboratorio Práctico de Configuración de Servidores.</strong> (25%)</li></ul><h3 id="📝-evaluacion-4-seguridad-perimetral-y-vpns-unidad-9" tabindex="-1">📝 Evaluación 4: Seguridad Perimetral y VPNs (Unidad 9) <a class="header-anchor" href="#📝-evaluacion-4-seguridad-perimetral-y-vpns-unidad-9" aria-label="Permalink to &quot;📝 Evaluación 4: Seguridad Perimetral y VPNs (Unidad 9)&quot;">​</a></h3><p><strong>Objetivo:</strong> Proteger la infraestructura de red contra accesos no autorizados.</p><ul><li><strong>Filtrado y Firewalls:</strong> Configuración de Iptables/Ipchains.</li><li><strong>Control de Acceso:</strong> Configuración de Proxy, TCP_wrappers y PAM.</li><li><strong>Túneles Seguros:</strong> Implementación de VPNs usando IPsec / Kerberos.</li><li><strong>Actividad:</strong> <strong>Laboratorio Práctico de Seguridad / Defensa Final.</strong> (25%)</li></ul><hr><h2 id="✅-resumen-del-trimestre" tabindex="-1">✅ Resumen del Trimestre <a class="header-anchor" href="#✅-resumen-del-trimestre" aria-label="Permalink to &quot;✅ Resumen del Trimestre&quot;">​</a></h2><p>Este es el trimestre más práctico y profesionalizante. Las evaluaciones progresan lógicamente: primero <strong>diseñan</strong> la red (Eval 1), luego calculan las <strong>direcciones lógicas</strong> (Eval 2), después le instalan los <strong>servicios</strong> (Eval 3) y finalmente la <strong>aseguran</strong> contra ataques externos (Eval 4).</p>',20)])])}const p=a(s,[["render",t]]);export{g as __pageData,p as default};
